insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 1, 'The Gas Processing Studio runs three unit operations over one gas stream. Which three?', '["Dehydration with glycol, sweetening with amine, and an inhibitor injection that keeps the water already present from forming a hydrate in the line below the plant.", "Dehydration, which takes water out with glycol; sweetening, which takes acid gas out with amine; and a dew point unit, which cools the gas by letting it down.", "A compositional flash that splits the wellstream, then glycol dehydration of the gas it releases, then amine sweetening of what the dehydration tab passes on.", "Glycol dehydration, molecular sieve polishing for the last of the water, and a refrigeration loop that drops the heavier ends out as a liquid product."]'::jsonb, 1, 'Three units, three balances, one stream. Inhibitor injection, a flash and a molecular sieve are all outside this engine, and the third unit cools by expansion rather than by refrigeration.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 2, 'A flowsheet asks this engine for the hydrate formation temperature of the dried gas at line conditions. What comes back?', '["No answer at all, because no hydrate boundary is in this engine. That margin belongs to the Flow Assurance engine in the Production module.", "An object carrying an error string that names the missing argument, since the routine is present and wants a subcooling correlation supplied to it.", "The temperature at which the dehydration tab stops answering, which is the guard edge at 140.000000 degF, because that is where the water answer and the hydrate question meet.", "The inlet water content of 53.450380 lb per MMscf, since a gas that dry is already below any hydrate point."]'::jsonb, 0, 'This is an absence rather than a refusal. Nothing prints, because the question never arises anywhere in the chain, and 140.000000 degF is the edge of a water fit rather than a hydrate line.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 3, 'The module states one rule in its header that decides which numbers a reader can see and which ones they have to accept. What is the rule?', '["Anything the published cases check is computed, and anything no golden reaches arrives as an input so that changing it cannot break a case.", "Anything carrying units is computed and anything dimensionless is typed, which is why the ratios in this module are the figures a person supplies.", "Everything that is a design choice or a chart value is an input with its customary range named, and everything computable from first principles is computed.", "Anything that moves with the gas is computed and anything that moves with the plant is typed, so the conditions are derived and the equipment is chosen."]'::jsonb, 2, 'The doctrine is about the ORIGIN of a number rather than about its units, its dimensionality or which gate can reach it. A chart value is an input even though it is very much about the gas.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 4, 'Which of these figures arrives as an input carrying a default rather than as something the module works out for itself?', '["The standard cubic feet in a pound mole, 379.483571856287, which the module builds from the gas constant and its own standard base.", "The glycol density of 69.568831168831 lb a ft3, formed from the density a gallon.", "The mole fraction of water in the gas at line conditions, which the module forms from a vapour pressure and a total pressure.", "The heat a pound of absorbed water takes in the still overhead, 1100.000000 Btu a lb."]'::jsonb, 3, 'The overhead is a declared value and an input with 1100.000000 as its default. The other three are computed or derived, so no reader has to accept them on trust.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 5, 'For four of its constants the digest asks the engine a question whose answer is that constant and nothing else, then divides the measurement by the export. Every one of the four comes back at 1.000000000000. What does that establish?', '["That the constant has a publication behind it, since a figure can only be measured against something that was measured first.", "That the name on the page and the number actually in use are the same number, and nothing whatever about whether the value is right.", "That the constant is a derived one rather than a declared one, because a declared value has no route out of a return value.", "That the golden reaches the same figure by a second road, which is what a ratio of exactly one between two independent answers means."]'::jsonb, 1, 'A ratio of 1.000000000000 rules out an export whose name is attached to a different number from the one in use. The water overhead is measured that way and is still a declared value with nothing to check it against.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 6, 'How is the standard cubic feet a pound mole, 379.483571856287, measured back out of the engine rather than read from the source?', '["By dividing the gallons a day by the gallons a minute that one call returns, which leaves the conversion the balance passed through standing on its own.", "By dividing the saturation answer by the mole fraction the same call returns, which strips the pressure ratio out and leaves the pound mole behind.", "By running the BTEX mole balance at one MMscfd, a million ppmv, a unit absorbed fraction and a unit molecular weight, where the answer is a million over that number and nothing else.", "By multiplying the gallons in a cubic foot of 7.480519480519 by the glycol density of 9.300000 lb a gallon, since the loop balance carries both."]'::jsonb, 2, 'Dividing a gallons a day by a gallons a minute measures the minutes in a day instead. Dividing the saturation answer by the mole fraction is a step towards the molecular weight of water, and the gallons in a cubic foot times the density a gallon gives 69.568831168831 lb a ft3.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 7, 'A reviewer proposes moving the glycol density away from 9.300000 lb a gallon. What else moves, and what can a gate do about the proposal?', '["The 69.568831168831 lb a ft3 the vessel sizing reads moves with it, because that figure is the density a gallon times the gallons in a cubic foot, and a gate can only pin a declared value so the change is a reviewed act.", "Nothing else moves, because the sizing carries a separate liquid density for a glycol column, and a gate re-derives the new figure from the publication the module cites.", "The standard cubic feet a pound mole moves with it, since both figures hang off the same standard base of 14.696000 psia and 519.670000 degR, and a gate fails the change on that arithmetic.", "The Magnus coefficients move with it, because the water the glycol picks up is what sets the loop balance, and a gate checks the new density against the measured value it exports."]'::jsonb, 0, 'One fluid has one density here and both the loop balance and the vessel sizing read it. No publication in this repository stands behind 9.300000, so pinning is the whole of what a gate can offer.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 8, 'The dehydration balance and the vessel sizing are shown to use one glycol density, at a ratio of 1.000000000000 between the two figures the module exports. What does that rule out?', '["Any future edit to the density, because a value a gate has pinned is one that cannot be moved again without the gate failing on the arithmetic.", "The density being a declared value, since a figure the digest has checked against a second route has stopped being a value with nothing behind it.", "An error in 9.300000 lb a gallon itself, which two agreeing routes would catch.", "One fluid carrying two numbers, so that nothing downstream can tell which of them it is holding."]'::jsonb, 3, 'Two numbers for one glycol is a defect whatever its size, and the ratio of 1.000000000000 says this module does not have one. It says nothing at all about whether 9.300000 is correct.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 9, 'The studio hands one of this module''s doors a state it has no answer for. What does the caller get?', '["A thrown error for a missing argument and an object for a value that is merely out of its domain, so a caller has to handle both shapes.", "An object with an `error` key carrying a named string, because this module throws nothing at all.", "The nearest answer inside the band with a note attached rather than a refusal.", "A null, so a caller can test the return value in one comparison."]'::jsonb, 1, 'This module throws nothing, so a caller gets a result it can look at and report and the studio can print the refusal rather than falling over. A note attached to a usable answer is what the publication limit and the pressure threshold do, which is a different behaviour.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 10, 'Why is an absence harder to work with than a refusal?', '["An absence returns a zero, and a zero reads as a small answer rather than as a missing one whenever it lands in a column of small answers.", "A refusal stops at the studio while an absence travels down the chain, so the missing quantity turns up inside the duty without ever being named.", "A refusal prints and cannot be used by accident, and an absence prints nothing at all, so a reader fills the gap in themselves.", "A refusal is a design choice and an absence is a defect in the code."]'::jsonb, 2, 'A dehydration answer of 6.399830 gpm and 0.697269 MMBtu an hour says nothing about a hydrate margin, and nothing in it flags that it says nothing. Each absence is a question that belongs to another engine rather than a hole.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 11, 'Two questions this engine has no answer for are a hydrate margin and the phase envelope of a reservoir fluid. Where does each belong?', '["The hydrate margin is the Flow Assurance engine in the Production module, and the phase envelope is the Fluid engine.", "The phase envelope is the Flow Assurance engine in the Production module, and the hydrate margin is the Fluid engine, which carries the water that forms one.", "Both belong to the Flow Assurance engine, which draws the envelope a hydrate line sits on.", "Both belong to this module''s dew point unit, which reaches the cold end where both would appear."]'::jsonb, 0, 'They are two engines and two questions. This module carries neither, and the dew point unit cools a gas rather than drawing an envelope or a hydrate line.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 12, 'The Associate tier follows the water chain from the line conditions to the duty and leaves the other two units to later tiers. Which of these is true of that chain?', '["The water chain is the only one of the three carrying published cases, so it is the only unit whose answers a learner can check against something outside the engine.", "A glycol loop is the only one of the three units the Studio gives a tab of its own, so it is the only unit a learner can work end to end on the page.", "The water duty is the largest of the three on both teaching streams, which makes it the unit where an error costs the most and the one to meet first.", "Nothing in it feeds back, so no step revises a step above it and a wrong duty can be traced in a single reading."]'::jsonb, 3, 'The chain runs one way, from the line conditions to the duty, so a wrong figure can be settled by reading it once. The other two units carry published cases as well, and the regenerator on the sour stream is much the larger duty of the two.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 13, 'UBIE arrives at 5.200000 mol percent CO2 and 1.400000 mol percent H2S and has to leave at 2.000000 and 0.000400. What does the engine report as going into the solution, and in what unit?', '["525.893013 gpm of solution, which is that same quantity expressed in the unit a circulation pump is bought in.", "25.242865 MMBtu an hour, which is the acid gas load expressed as the heat the regenerator needs to strip it back out.", "10666.2009 lbmol of acid gas a day.", "10666.2009 lb a day, since a mole balance ends in a mass once the molecular weight of the acid gas has been applied."]'::jsonb, 2, 'Sweetening is a mole balance and the pickup is 10666.2009 lbmol a day. The gpm and the MMBtu an hour are real figures on this stream that answer later questions in the chain.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 14, 'The module fixes one standard base, at 14.696000 psia and 519.670000 degR. Which exported figure follows directly from it?', '["The Rankine offset of 459.670000 degR, which is how every temperature in the module reaches the absolute scale the correlations want.", "The standard cubic feet in a pound mole, 379.483571856287, which is the gas constant of 10.731600 times that temperature over that pressure.", "The gallons in a cubic foot, 7.480519480519, which the module needs before any volume at the standard base can be quoted in gallons.", "The glycol density of 69.568831168831 lb a ft3, which is a mass in the volume unit the standard base is written in."]'::jsonb, 1, '379.483571856287 is the standard base and the gas constant in one expression. The Rankine offset and the gallons in a cubic foot are fixed conversions that owe the base nothing.'),
  ('gasprocessing', 'beginner', 'module', 'm01-what-this-engine-conditions', 15, 'The minutes in a day and the factor of 24000000 are established as groups rather than one part at a time. Why?', '["The engine never uses their parts separately, so nothing outside it can pull them apart.", "Both are exact conversions between units, and measuring one part of an exact conversion would add nothing that its definition does not already give.", "Both are declared values, and a declared value can only be pinned in one place under one name rather than checked piece by piece.", "Neither has a published case behind it, so the only route left is to take whatever the engine returns and record it under the name it was asked for."]'::jsonb, 0, 'The gallons a day over the gallons a minute of one call gives 1440.000000000, and the gallons a day times the duty a gallon over the duty in MMBtu an hour gives 24000000. Each is a measurement of a product rather than of its factors.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 1, 'OBIAFU sits at 950.000000 psia and 104.000000 degF, where the vapour pressure of water is 1.069612 psia. How does the method reach a mole fraction of water in the gas of 0.001125908?', '["By dividing the vapour pressure by the total pressure and then correcting the result for the compressibility the gas has at those conditions.", "By taking the vapour pressure to the total pressure over the standard pressure, so that the fraction is referred back to the standard base the pound mole is written at.", "By dividing the vapour pressure by the total pressure, which is the whole of the physical step.", "By dividing the vapour pressure by the difference between the total pressure and itself, since the gas the water is mixing into is the part of the pressure that is not water."]'::jsonb, 2, 'Ideal vapour liquid equilibrium over liquid water is one division: 1.069612 over 950.000000 is 0.001125908. No compressibility and no standard base enter here.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 2, 'In the saturation division, what does each side carry?', '["The numerator carries the whole temperature dependence and no pressure at all, and the denominator carries the whole pressure dependence and enters only as a divisor.", "The numerator carries the temperature and the gas gravity together, and the denominator carries the pressure, so both sides know something about the gas itself.", "The numerator carries the temperature, and the denominator carries the pressure along with a second and separate pressure effect that acts on the vapour pressure above it.", "The numerator carries the pressure the water exerts at the surface of the pool, and the denominator carries the temperature converted to the absolute scale the fit was written on."]'::jsonb, 0, 'The vapour pressure of water at 104.000000 degF is 1.069612 psia whatever the gas around it is doing, and there is no separate pressure effect anywhere in the method.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 3, 'The vapour pressure of water reads 0.255814 psia at 60.000000 degF, 0.506169 at 80.000000, 1.069612 at 104.000000 and 2.904091 at 140.000000. What is a reader entitled to take from those four rows?', '["The shape of the curve, by dividing the highest reading by the lowest and quoting the result as how steeply the vapour pressure climbs over that span.", "The direction, which is that the vapour pressure rises with temperature across the whole of the table.", "The rate of climb per degree, by taking the difference between two adjacent rows and dividing it by the difference in temperature between them.", "A check on the fit, since a vapour pressure that rises smoothly over four readings is a fit that has been validated across the span between them."]'::jsonb, 1, 'This course prints the figures a ratio would need and does not print the ratio, which means the two readings are not in a relationship this engine computes. A number nobody computed reads exactly like one somebody did.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 4, 'Where do the numbers behind the vapour pressure come from, and what standing do they have?', '["A steam table the module carries internally, read at the gas temperature and interpolated between the rows the table happens to hold.", "A correlation the module derives from the standard base of 14.696000 psia and 519.670000 degR, so the coefficients follow from figures already exported.", "A published equation the golden also uses, which is why the engine and the golden agree to every figure they both print on the four cases.", "A Magnus form fit whose three coefficients, 0.610940, 17.625000 and 243.040000, are declared constants with no publication in this repository behind them."]'::jsonb, 3, 'The coefficients are exported under their own names and declared, which means customary. The golden deliberately uses a DIFFERENT published vapour pressure equation, which is why its ratios sit near one rather than at one.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 5, 'Turning a mole fraction of 0.001125908 into 53.450380 lb of water per MMscf passes through two constants. Which two?', '["The standard cubic feet in a pound mole, 379.483571856287, and the molecular weight of water, 18.015280.", "The gallons in a cubic foot, 7.480519480519, and the glycol density of 9.300000 lb a gallon, which together turn a gas volume into a mass.", "The gas constant of 10.731600 and the Rankine offset of 459.670000, which are what the gas law needs to give a density at line conditions.", "The molecular weight of dry air, 28.962500, and that of water, 18.015280."]'::jsonb, 0, 'A million standard cubic feet is a definite number of pound moles at 379.483571856287 scf a lbmol, the fraction says what share of them are water, and 18.015280 turns that share into pounds.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 6, 'A plant doubles its gas rate and nothing else changes. What happens to the water content of 53.450380 lb per MMscf?', '["It doubles, since twice as much gas carries twice as much water past one point.", "Nothing. The content is a property of the gas at its conditions and the rate is nowhere in the division that produced it.", "It falls, since the same vapour pressure is shared across twice the molecules.", "It rises slightly, because the higher velocity shortens the contact time and leaves the gas further from the equilibrium the method assumes."]'::jsonb, 1, '53.450380 is a number per MMscf, and the per is doing real work. The rate arrives later in the chain and multiplies a removal rather than this content.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 7, 'On the water content surface, what happens going down a column and what happens going across a row?', '["Down a column the content falls, because a hotter gas expands and holds its water at a lower mole fraction. Across a row it rises, because compression brings the gas and the water closer together.", "Down a column the content rises with the vapour pressure. Across a row it also rises, slowly, because the departure from ideal mixing grows with pressure and adds water back.", "Down a column the content rises, because the vapour pressure in the numerator rises with temperature. Across a row it falls, because the same vapour pressure is divided by a larger total pressure.", "Down a column the content rises with the vapour pressure. Across a row it holds nearly level, because the pressure cancels between the mole fraction and the pound mole."]'::jsonb, 2, 'At 200.000000 psia the content runs from 60.721539 at 60.000000 degF to 689.331762 at 140.000000, and at 60.000000 degF it runs from 60.721539 at 200.000000 psia down to 8.096205 in the 1500 psia column.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 8, 'Sixteen cells of the water surface vary gently and smoothly. What does that smoothness establish?', '["That the fit has been checked across the whole surface, since a formula that wandered between the published points would show it as a kink somewhere in the table.", "That the gas behaves close to ideally across the whole surface, because a real gas departure large enough to matter would bend one of the sixteen readings away from its neighbours.", "That the surface was drawn from measured data, since a family of curves this regular is what a chart built from many measurements at many conditions looks like.", "Nothing about the gas. It is one formula evaluated at sixteen sets of inputs, so the smoothness belongs to the formula."]'::jsonb, 3, 'Nothing in the table was solved for and nothing was measured. An answer that varies gently across a table has been evaluated across it, which is a different claim from having been checked across it.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 9, 'The engine answers at -49.000000 degF with 0.153343 lb per MMscf and at 140.000000 degF with 275.732705, and refuses at -49.000001 and at 140.000001. What is that guard doing at its edges?', '["Excluding them, since the edge value is exactly where the fit stops describing the curve and an answer there would be an extrapolation of the coefficients.", "Including them, because a guard that refused its own stated limit would be as wrong as one that accepted anything at all.", "Rounding to the edge, so that a temperature a millionth of a degree outside is answered at the edge value and flagged with a note rather than refused.", "Testing the converted value rather than the typed one."]'::jsonb, 1, 'The band holds from -45 to 60 degC, which is -49 to 140 degF, and the engine answers at exactly the edge and refuses a millionth of a degree outside it.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 10, 'Between 50 degC and the guard at 60 degC the engine answers and attaches a note. What does the note say is going on?', '["The coefficients were published over a narrower band than the module guards, so inside the gap the fit is an extrapolation of itself, and it reads about 0.8 percent above the Antoine fit at 60 degC.", "The gas has passed the pressure at which ideal mixing starts to understate the water a real gas carries, so the answer should be replaced by a chart reading.", "The fit has left the range the engine will answer over, so the number returned beside the note is the value at the edge rather than at the temperature asked for.", "The temperature has reached the point where liquid water is no longer the phase the fit was regressed against, so the answer describes a different equilibrium."]'::jsonb, 0, 'The publication limit is about the CURVE the engine draws and it warns rather than refusing, because the fit still tracks the curve there and the engine can say how far it has drifted.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 11, 'Above about 1000.000000 psia a different note appears. What is it warning about, and why can no arithmetic inside this module settle it?', '["The fit is being extrapolated beyond the pressures its coefficients were regressed at, so the curve has drifted and the note says by roughly how much.", "The total pressure is approaching the point where it no longer exceeds the vapour pressure of water, which is the state the engine refuses just below.", "Ideal mixing understates the water a real gas carries and the departure grows with pressure, so the answer is a screening number and the design number is a chart reading.", "The compressibility the sizing routine computes has left the band its correlation is valid over, so the density the answer rests on can no longer be formed."]'::jsonb, 2, 'The first two limits are about the curve the engine draws. This one is about whether that curve is the right curve at all, and the McKetta-Wehe correction the note names lives outside this module.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 12, 'An engineer types 200.000000 degF into the gas temperature box of the Studio. What does the dehydration tab do?', '["It answers and attaches the publication note, because 200.000000 degF is above the band the coefficients were published over and the engine prefers a flagged number to a refusal.", "It answers and attaches the chart note, because a temperature that high only arises on a gas whose pressure is also above the threshold where the correction matters.", "It clamps the temperature to the guard edge of 140.000000 degF and answers there, so the whole tab keeps returning numbers while the note records what was typed.", "It refuses by name, giving the band in both units together with the typed temperature converted, which is 93.3 degC."]'::jsonb, 3, 'The box takes any number and the whole tab refuses this one. Being told the band, the unit conversion and your own figure is being told what to change and by how much.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 13, 'A total pressure exactly equal to the water vapour pressure at the gas temperature is refused, in the same words as a pressure below it. Why refuse the equality?', '["The division would return a mole fraction above one at the equality, which is not a fraction at all, so the arithmetic below it fails on its own.", "A gas at exactly its own water vapour pressure is all water and nothing else, so refusing the equal case is right rather than over strict.", "The two cases share one guard, and a guard written with a strict comparison on one side has to refuse the equality on the other to stay consistent.", "The vapour pressure is quoted to four figures in the message."]'::jsonb, 1, 'The refusal reads that the total pressure must exceed the water vapour pressure of 1.0696 psia at 104 degF, or the gas is not a gas. It is one guard read from either side of its own limit.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 14, 'On the four published water cases the engine over golden column reads 1.001865077, 1.004159870, 1.002457408 and 1.006379500. Why is that a better result than a column of exact ones?', '["The departures are the real gas correction the golden applies and the engine does not, so the column measures how much ideal mixing is understating the water.", "A golden that agreed exactly would have been regenerated from the engine.", "The golden comes from a different published vapour pressure equation, so two independent fits of one physical curve are meeting inside their shared band.", "All four figures sit above one, so the engine is conservative on every case."]'::jsonb, 2, 'Two copies of one fit agreeing exactly says a transcription was faithful. Two published fits meeting near one says two roads met, which is the whole value of the check.'),
  ('gasprocessing', 'beginner', 'module', 'm02-how-much-water-a-gas-carries', 15, 'What does the module give up by computing a vapour pressure instead of reading a chart?', '["The real gas behaviour a chart has built into it, because the chart was drawn from gas that was measured and the fit was drawn from pure water.", "Reproducibility, because a fit carries rounding a chart reading does not.", "The ability to answer away from the published points, which only a chart has.", "Nothing at all, since the McKetta-Wehe correction the engine warns about above 1000.000000 psia is the chart behaviour restored to the calculation."]'::jsonb, 0, 'The trade is the character of this method. It is fast, transparent and exactly reproducible, and it is describing an idealisation of the real thing.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 1, 'OBIAFU arrives at 53.450380 lb of water per MMscf and the contract allows 7.000000 lb per MMscf to leave. What does the unit have to remove, per MMscf?', '["53.450380 lb, the whole of the water the gas arrived with at line conditions.", "46.450380 lb, which is the inlet content less the outlet spec.", "7.000000 lb, which is the figure the contract names.", "2879.9235 lb, which is the removal this stream is actually sized on."]'::jsonb, 1, 'The load is one subtraction and the answer stays per MMscf. Reporting the whole inlet content overstates the duty, and 2879.9235 is the same load a day later in the chain, at 62.000000 MMscfd.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 2, 'At a fixed 62.000000 MMscfd and a fixed 3.200000 gal per lb, tightening the spec from 7.000000 to 0.500000 lb per MMscf takes the water out from 2879.9235 to 3282.9235 lb a day. Why can that column not go on rising without end?', '["The inlet content is a ceiling, since a unit cannot remove more water than arrived in the gas.", "The customary circulation band closes the column off, because a load above it would put the ratio outside 2.000000 to 5.000000 gal per lb.", "The still temperature of 375.000000 degF caps what the reboiler can boil off.", "The rich glycol drops below the 90 the module accepts as a lean strength."]'::jsonb, 0, 'A tighter spec raises the load, the circulation and the duty together, and the load approaches 53.450380 lb per MMscf rather than growing without limit.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 3, 'A data sheet reports 53.450380 lb per MMscf as the water this dehydration unit removes. What is wrong with that?', '["It is the load at a spec of 7.000000 rather than at this contract''s spec.", "It is a per MMscf figure where a removal has to be quoted a day.", "It is the water a gallon of glycol picks up rather than the water the gas gives up in the contactor.", "It is the inlet content rather than the load, so it overstates the duty by whatever the spec allows to leave."]'::jsonb, 3, 'The inlet content and the load live one subtraction apart and are easy to confuse on a busy sheet. 46.450380 is the load and 53.450380 is what arrived, and both are already quoted per MMscf.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 4, 'The water content, the spec and the load are all per MMscf. Where does the gas rate enter the chain?', '["At the saturation step, where the rate sets how much gas the vapour pressure of 1.069612 psia is being shared across.", "At the circulation ratio, where the gallons a pound of water needs are scaled to the size of the plant.", "At one multiplication, which turns the load per MMscf into a load a day.", "At the reboiler, where the duty a gallon is fired up."]'::jsonb, 2, '46.450380 lb per MMscf at 62.000000 MMscfd is 2879.9235 lb a day. The answer stops being a property of the gas and starts being a property of the plant.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 5, 'Down the rate table the water out, the circulation and the reboiler all move, and the Btu a gallon reads 1815.8525 at every rate. Which two figures in a dehydration answer are intensive?', '["The water content in lb per MMscf and the duty per gallon in Btu.", "The water removed in lb a day and the duty per gallon in Btu, since neither of them mentions a pressure or a temperature anywhere.", "The circulation in gpm and the duty in MMBtu an hour, since both are rates and a rate is a property rather than a quantity.", "The content in lb per MMscf and the removal in lb a day."]'::jsonb, 0, 'An intensive figure does not know how much material there is. The lb a day, the gallons a day, the gpm and the MMBtu an hour are the same load with the rate already inside them.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 6, 'The rate runs from 10.000000 to 250.000000 MMscfd and the Btu a gallon stays at 1815.8525. What is that column a property of?', '["The gas, since the pressure and the temperature settled it before any rate was named.", "The contract, since the spec decides what each gallon has to give up in the still.", "The plant, since it is the firing rate divided by the gallons the pump moved.", "The glycol loop, and what one gallon of it costs."]'::jsonb, 3, 'The rate only decides how many gallons there are. At 250.000000 MMscfd the removal is 11612.5949 lb a day and 25.805766 gpm, on a gallon that still costs 1815.8525 Btu to heat and strip.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 7, 'Who supplies the circulation ratio, and what does the engine do about it?', '["The engine derives it from the outlet spec, since the dew point a lean glycol delivers decides the gallons.", "A person supplies it, and the engine reports what it costs without having an opinion on what it should be.", "The customary band supplies it, since the engine takes the middle of 2.000000 to 5.000000 gal per lb.", "The published cases supply it, since a ratio no golden covers is one nothing here can check."]'::jsonb, 1, 'The content came from the conditions, the load from the contract and the rate from the reservoir. The circulation ratio came from a person, and a module with no dew point chart in it is in no position to choose one.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 8, 'As the circulation ratio is raised from 2.000000 to 5.000000 gal per lb, which way do the gallons a minute, the Btu a gallon and the MMBtu an hour move?', '["All three rise, because more glycol is being moved and everything charged on a gallon is now charged on more gallons.", "The gpm rises, the Btu a gallon rises with it, and the MMBtu an hour falls because each pound is spread thinner.", "The gpm rises, the Btu a gallon falls, and the MMBtu an hour rises.", "All three fall except the gpm."]'::jsonb, 2, 'From 3.999894 to 9.999734 gpm, from 2073.6650 to 1661.1650 Btu a gallon, and from 0.497666 to 0.996673 MMBtu an hour. Three columns and they do not move together.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 9, 'Why does the Btu a gallon fall while the MMBtu an hour rises as the ratio goes up?', '["Each gallon carries less water, so each needs less heat to boil it out, while there are more gallons to heat.", "The sensible term falls because a lightly loaded gallon reaches the still sooner.", "The overhead is charged a day rather than a gallon, so more gallons dilute it.", "The reflux is applied to the gallons rather than to the water in them."]'::jsonb, 0, 'The sensible half sits at 1386.1650 Btu a gallon the length of that table, because the temperature rise per gallon never changed. The overhead half is what moves, from 687.5000 at 2.000000 gal per lb to 275.0000 at 5.000000.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 10, 'At a circulation ratio of 3.200000 gal of glycol per lb of water, how much water does one gallon pick up in the contactor?', '["3.200000 lb, which is the ratio read as a load on the gallon.", "0.312500000 lb, which is one over the ratio.", "0.074400000 lb, which a lean gallon already carries.", "1.000000000 lb, one pound to every gallon circulated."]'::jsonb, 1, 'Turning the ratio over is the most useful move in the glycol half of this course, because every per gallon quantity downstream is built on it. The 0.074400000 lb is what a lean gallon at 99.200000 weight percent already carries, which is a different figure.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 11, 'OBIAFU removes 2879.9235 lb of water a day at 3.200000 gal per lb. What is the circulation, and what did the arithmetic pass through?', '["6.399830 gpm, by way of 9215.7553 gallons a day and the group factor of 24000000 the duty uses.", "9215.7553 gpm, since a ratio in gal per lb already delivers a volume rate.", "2.999920 gpm, read at the customary low edge of 2.000000 gal per lb.", "6.399830 gpm, by way of 9215.7553 gallons a day and the 1440.000000000 minutes in a day."]'::jsonb, 3, 'A load a day, a ratio, and the minutes in a day, in that order. The 24000000 is the group that turns a duty a gallon into MMBtu an hour, which is a different conversion at a different place in the chain.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 12, 'This module never uses the hours or the minutes separately. How was the 1440.000000000 minutes in a day established for it?', '["By reading the digits out of the source and pinning them under a name.", "By taking the gallons a day and the duty a gallon against the duty in MMBtu an hour.", "By asking one call for a gallons a day and a gallons a minute and dividing the first by the second.", "By checking it against the three published TEG cases."]'::jsonb, 2, 'That is a measurement rather than a reading. It proves that whatever the engine divides by, it divides by 1440.000000000, which is a stronger statement than finding the digits in a file.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 13, 'The engine is silent at exactly 2.000000 and exactly 5.000000 gal per lb and warns at 1.999999 and at 5.000001. What kind of band is that, and does it still answer?', '["A customary band with inclusive edges, and it answers either way.", "A physical band with inclusive edges, which refuses anything outside them.", "A customary band with exclusive edges, answering throughout.", "A publication band, extrapolating beyond its edges."]'::jsonb, 0, 'Customary is a statement about what other people build. A unit outside it is unusual rather than impossible, which is why the engine warns and still answers.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 14, 'At 0.250000 gal per lb the warning carries a second sentence beyond the customary band. What does that sentence say?', '["That the contactor can no longer reach the outlet spec at this loading, so the dew point the unit is sold on is not one the loop delivers.", "That the rich glycol returns at 69.37 weight percent, below the 90 this module accepts as a lean strength, so the loop is carrying more water than a glycol loop is meant to.", "That the duty has left the range the published TEG cases cover.", "That each gallon is picking up 4.000000000 lb of water."]'::jsonb, 1, 'The first half of the warning is advisory and the second half is a statement about the loop. At 1.000000 gal per lb the rich glycol still returns at 89.568932039 weight percent, which is under the same limit.'),
  ('gasprocessing', 'beginner', 'module', 'm03-the-water-a-unit-takes-out', 15, 'The lean glycol strength is refused at exactly 90.000000000 and at exactly 100.000000000 weight percent, and answered at 90.000001000 and 99.999999000. Why are both edges excluded?', '["Both edges are where the loop water balance divides by zero, so the module refuses them and answers a millionth either side of each.", "Both sit outside the band the published cases were written over, and a value no golden covers is refused rather than warned about.", "Below 90 the loop is not a dehydration loop, and 100 is a purity no regenerator reaches.", "Below 90 the rich would return stronger than the lean."]'::jsonb, 2, 'A customary band includes its edges because an edge value is an ordinary design. A physical band excludes them because the edge is where the description stops being true, and the two reasons here are different from each other.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 1, 'The sensible term on OBIAFU is built from three things and a temperature rise. Which three, and what do they give?', '["0.312500000 lb of water a gallon, 1100.000000 Btu a lb and the reflux ratio of 0.250000, giving 429.6875 Btu a gallon.", "9.300000 lb a gallon, 1100.000000 Btu a lb and the rise from the absorber to the still, giving 1815.8525 Btu a gallon.", "9.300000 lb a gallon, 0.550000 Btu per lb per degF, and the rise from 104.000000 degF to 375.000000 degF, giving 1386.1650 Btu a gallon.", "69.568831168831 lb a ft3, 0.550000 Btu per lb per degF and the still at 375.000000 degF, giving 1386.1650 Btu a cubic foot."]'::jsonb, 2, 'Mass times specific heat times rise. The overhead term, built from the water a gallon carries and 1100.000000 Btu a lb, is charged on the water rather than on the solvent, and the density this term reads is the one per gallon.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 2, 'A gallon of glycol goes round the loop having picked up no water at all. What happens to the sensible term?', '["Nothing. It is the cost of moving the solvent rather than of doing anything to it.", "It falls to zero, since a gallon carrying no water has nothing for the still to take back out of it.", "It falls in proportion, since the term is charged on the mass of the gallon and a dry gallon weighs less than a wet one.", "It rises, since a gallon carrying no water needs no heat for the overhead and the still spends all of its firing on the solvent."]'::jsonb, 0, 'The sensible half heats the glycol from the absorber to the still whether the gallon is carrying much water or little. Nothing about water enters until the overhead term.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 3, 'Across still temperatures of 340.000000, 375.000000 and 400.000000 degF the sensible term reads 1207.1400, 1386.1650 and 1514.0400 Btu a gallon while the overhead reads 429.6875 at all three. Why does the overhead not move?', '["The overhead is charged on the reflux, and the reflux ratio was not what moved.", "The overhead is quoted a day rather than a gallon, so a per gallon table cannot show it moving.", "The still temperature only reaches the overhead once it is above 400.000000 degF, which is where the glycol itself begins to degrade.", "Boiling a pound of water out of the gallon costs what it costs however hot the vessel is."]'::jsonb, 3, 'The still temperature has exactly one place to act in this balance, which is the rise the sensible term is built on. The total moves down that table only because the sensible half moved.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 4, 'At 3.200000 gal per lb a gallon carries 0.312500000 lb of water, and the overhead the module charges is 1100.000000 Btu a lb. What do those two give, and what does the figure leave out?', '["429.6875 Btu a gallon, which is the overhead with the reflux already inside it.", "343.7500 Btu a gallon, which is the overhead with no reflux at all.", "1386.1650 Btu a gallon, which is the overhead before the sensible half is added to it.", "343.7500 Btu a gallon, which is the whole overhead, since the reflux is charged on the sensible term instead."]'::jsonb, 1, '0.312500000 times 1100.000000 is 343.7500, and it is the first row of the reflux table. The reflux ratio of 0.250000 then takes it to 429.6875.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 5, 'The 1100.000000 Btu a lb the still overhead is charged at stands for what, exactly?', '["The latent heat of pure water at the still temperature of 375.000000 degF, read off a steam table and carried inside the module under its own exported name.", "The heat a gallon of glycol needs to reach the still, charged on the water in it.", "Boiling absorbed water back out of a glycol solution at still conditions, which is a slightly different thing from the latent heat of pure water.", "The heat the reflux returns to the still, charged once on every pound."]'::jsonb, 2, 'A latent heat is a physical property and this module does not compute one. It takes a figure that stands for the vaporization the still actually performs and declares it, with no publication in this repository behind it.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 6, 'What does a reflux ratio of 0.250000 do to the overhead term?', '["It adds a quarter of the water vaporization on top of itself, taking 343.7500 Btu a gallon to 429.6875.", "It sends a quarter of the overhead back down the column unheated, so the term falls to 343.7500 Btu a gallon.", "It splits the overhead into a boiled quarter and a condensed remainder, which is why 429.6875 is quoted rather than 550.0000.", "It charges a quarter of the sensible term again."]'::jsonb, 0, 'Some of what is boiled overhead condenses at the top of the column and runs back down to be boiled again, and the reboiler pays for that returning water twice.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 7, 'The reflux table carries the overhead, the total and the reboiler duty and does not carry the sensible term. Why is the sensible term absent?', '["It is inside the total column already, so printing it beside the total would be printing one number twice.", "It is charged on the gallons a day rather than on a gallon, so it belongs beside the duty an hour.", "It moves with the reflux but by so little across 0.000000 to 0.600000 that the column would read the same figure six times.", "It never moves when the reflux ratio moves, because reflux is a water question and the sensible term is a solvent question."]'::jsonb, 3, 'The overhead runs from 343.7500 to 550.0000 Btu a gallon across that table while the sensible half sits where the still temperature and the absorber temperature put it.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 8, 'Reading only the reflux table, a designer concludes that the cheapest still runs with no reflux at all. What is wrong with the conclusion?', '["The table holds the circulation ratio fixed, and a still with no reflux needs a higher ratio to reach the same rich loading.", "Reflux is a trade between duty and glycol losses, and this module prices only the duty side of it.", "A reflux ratio of 0.000000 is one the engine refuses.", "The table prices the reflux against the total rather than against the overhead, so the first row understates what no reflux costs."]'::jsonb, 1, 'A still with no reflux sends glycol overhead with the water, so the loop loses solvent that was paid for. Glycol carryover is not a quantity this engine computes, which is why the table supports the conclusion and the plant does not.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 9, 'On OBIAFU the two heat terms are 1386.1650 and 429.6875 Btu a gallon. What is the total, and what share of it is sensible?', '["1815.8525 Btu a gallon, of which 0.763369 is the overhead half.", "1729.9150 Btu a gallon, of which 0.763369 of it is sensible.", "1815.8525 Btu a gallon, of which 0.763369 is sensible.", "1815.8525 Btu a gallon, and the course prints no share for the two halves."]'::jsonb, 2, 'The sensible over the sum is the one comparison between the two heat terms this course computes, and it says the larger part of this reboiler is warming glycol up.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 10, 'The loop moves 9215.7553 gallons a day, each needing 1815.8525 Btu. How does that become 0.697269 MMBtu an hour?', '["The product is divided by the group factor of 24000000, which carries the hours in a day and the Btu in a MMBtu.", "The product is divided by the 1440.000000000 minutes in a day and then again by the million Btu that a MMBtu carries.", "The gallons a day are turned into gpm first, and 6.399830 gpm is multiplied by the duty a gallon.", "The product is divided by the hours in a day alone, and the answer is then quoted in MMBtu."]'::jsonb, 0, 'A duty a day divided by the hours in a day and by the Btu in a MMBtu. The minutes in a day belong to the circulation, which is a different conversion earlier in the chain.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 11, 'The sensible term is built on a rise. Which temperature sets the bottom of it, and why that one?', '["The still temperature of 375.000000 degF, since the rise is measured downwards from the temperature the regenerator itself actually runs at.", "The gas temperature of 104.000000 degF, because a gallon leaves the bottom of the contactor at the temperature of the gas it just met.", "The standard temperature of 519.670000 degR, which is the base that every temperature in this module is ultimately referred back to.", "The reboiler edge of 340.000000 degF, which is the lowest still the table carries."]'::jsonb, 1, 'Absorber to still. Cooling the gas before the contactor therefore shortens the rise as well as lowering the inlet water content, and the engine takes both temperatures as typed inputs.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 12, 'What is inside the 0.697269 MMBtu an hour, and what is not?', '["The reboiler and the still overhead condenser, since the reflux the condenser returns is charged inside the overhead term.", "The reboiler and the gas and glycol exchanger, since both sit inside the loop the duty is charged on.", "The whole glycol package, since every heat term the module names has been added into it by this point in the chain.", "The reboiler and nothing else, so the pump, the exchanger, the flash vessel and the cooling of the lean glycol are all absent."]'::jsonb, 3, 'It is a firing rate for one vessel. The reflux appears in the duty as heat the reboiler pays again, rather than as a condenser being sized.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 13, 'A duty looks too high. What does splitting it into a sensible half and an overhead half tell a designer that one figure cannot?', '["Whether the duty was computed at the right rate, since only the overhead half carries the gas rate into the figure.", "Whether the still temperature was typed or taken from the default, since the sensible half is the only term that carries it.", "Which remedy applies, since a sensible-heavy duty and an overhead-heavy duty point in opposite directions.", "Whether the answer sits inside the published TEG cases."]'::jsonb, 2, 'A duty dominated by the sensible term is a circulation or a still temperature question. A duty dominated by the overhead is a water question, and more circulation rather than less is the remedy there.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 14, '1729.9150 Btu a gallon appears twice in this module: once at a reflux ratio of 0.000000 and once at a circulation ratio of 4.000000 gal per lb. Do the two rows say the same thing?', '["No. The duties an hour beside them are 0.664270 and 0.830337 MMBtu, because the two rows hold different numbers of gallons.", "No. The first is a total and the second is an overhead, so only one of the two carries the sensible term inside it.", "Yes. A duty a gallon is a property of the loop, so two rows carrying the same figure describe the same loop.", "Yes, on the duty a gallon, and the two differ only in the warning the second row carries."]'::jsonb, 0, 'A duty a gallon says what one gallon costs and says nothing about how many gallons there are. The same figure is reached by cutting the reflux to nothing and by circulating more glycol per pound.'),
  ('gasprocessing', 'beginner', 'module', 'm04-what-the-reboiler-pays-for', 15, 'A reboiler duty is quoted with no other figure beside it. Which decisions have been hidden?', '["The gas pressure and the gas temperature, which fixed the water content the whole duty is charged on.", "The still temperature, the absorber temperature, the circulation ratio and the reflux ratio, along with the rate that set the gallons.", "The outlet spec and the lean glycol strength, which between them decide what each gallon has to give up in the still.", "The glycol density and the specific heat, which are the two declared values the sensible term is assembled from."]'::jsonb, 1, 'Two plants at the same duty can have arrived there by different routes, and the route decides what would happen if anything moved. The conditions and the spec reach the duty through the load rather than through the duty a gallon.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 1, 'In the OBIAFU chain, what stands between the mole fraction of 0.001125908 and the load of 46.450380 lb per MMscf?', '["The rate of 62.000000 MMscfd, which turns a fraction into a quantity, and then the contract spec.", "The pound mole and the molecular weight of water, which give the content of 53.450380, and then the contract spec of 7.000000.", "The circulation ratio of 3.200000 gal per lb, which is where a fraction becomes a load the loop can carry.", "Nothing but the spec, since the mole fraction is already a figure in lb per MMscf."]'::jsonb, 1, 'A mole fraction becomes a content through two constants, and the content becomes a load through one subtraction. The rate arrives after the load and the ratio after that.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 2, 'No step in this chain revises a step above it. What does that property buy a learner?', '["A wrong figure can be traced in one reading, because every figure has one parent and one operation above it.", "A guarantee that the answer is right, since a calculation with no feedback in it has nowhere for an error to enter.", "The ability to run the chain backwards from the duty at every step.", "A shorter calculation, since nothing has to be evaluated twice and no step waits on a step below it."]'::jsonb, 0, 'If the duty is wrong then the gallons a day are wrong or one of the heat terms is wrong. An absorber with stages or a compressor with an efficiency curve gives no such single place to look.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 3, 'Two conditions enter at the top of the chain that runs from the line conditions to the duty, and are never mentioned again in it. Which two, and where is the last place they act?', '["The pressure and the temperature, and the last place they act is the vessel the gas rises through.", "The spec and the rate, and the last place they act is the water removed a day.", "The gas temperature and the still temperature, and the last place the two of them act is the sensible heat term.", "The pressure and the temperature, and the last place they act is the water content."]'::jsonb, 3, 'Once the content is fixed the line conditions have no further say in the chain that ends at the duty. The vessel the gas rises through does care what pressure the gas is at, and it sits outside this chain rather than inside it. The still temperature is a design choice entering much lower down, inside one of the two heat terms.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 4, 'A circulation of 6.399830 gpm is quoted on its own, with nothing beside it. What can be said about how it was arrived at?', '["That the ratio was inside the customary band, since a circulation the engine reported without a warning is one it accepted.", "That the rate was 62.000000 MMscfd, since a gpm carries the rate inside it and can be read back to it.", "Nothing. Two of the load a day, the ratio and the circulation always give the third, and one of the three on its own gives none of them.", "That the spec was met, since the circulation is what the load demands and the load is what the spec set."]'::jsonb, 2, 'Given a gpm and the load a day the ratio follows. Given a gpm and the ratio the load a day follows. A single quoted circulation is almost useless on its own.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 5, 'Which of these could NOT have moved a circulation figure, with nothing else on the data sheet changed?', '["The reflux ratio.", "The circulation ratio.", "The gas rate in MMscfd.", "The gas temperature."]'::jsonb, 0, 'The circulation follows from the load a day, the circulation ratio and the minutes in a day. The reflux ratio and the still temperature act on the heat terms alone, and the gas temperature reaches the circulation through the inlet water content.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 6, 'What does the lean glycol strength act on, and what does it leave alone?', '["It acts on the outlet spec the unit can deliver, and leaves the water removed a day alone.", "It acts on the loop water balance, which is what a gallon is carrying, and leaves the number of gallons alone.", "It acts on the sensible heat term and leaves the overhead alone.", "It acts on the customary band, since a weaker lean narrows the ratios the engine will accept, and leaves the duty alone."]'::jsonb, 1, 'At 99.200000 weight percent a lean gallon already carries 0.074400000 lb of water and the rich glycol comes back at 95.975032510. The engine says on every answer that the dew point a lean strength delivers is a chart it does not carry.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 7, 'A rate change and a ratio change both raise the circulation. What does each one drag along with it?', '["A rate change moves the duty a gallon, and a ratio change moves the water removed a day.", "Both move the water removed a day, and only the ratio change moves the duty a gallon.", "A rate change moves the water content, and a ratio change moves the load per MMscf.", "A rate change moves the water removed a day and everything below it, and a ratio change leaves the water removed where it was."]'::jsonb, 3, 'The same pounds are still coming out of the same gas when the ratio moves. What moves is how much glycol carries them and what a gallon costs to regenerate.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 8, 'Which figure does the gas rate reach, the Btu a gallon or the MMBtu an hour?', '["Both, because the duty an hour is the duty a gallon with the gallons applied and the rate is inside both figures.", "The Btu a gallon only, because the gallons a day are what the rate multiplies and the hourly duty is a firing rate.", "The MMBtu an hour only, because the rate decides how many gallons there are rather than what one costs.", "Neither, because both duty figures are charged on the loop."]'::jsonb, 2, 'The Btu a gallon reads 1815.8525 at 10.000000, 62.000000 and 250.000000 MMscfd. The still temperature, the absorber temperature, the circulation ratio and the reflux ratio are what reach it.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 9, 'An engineer offers the Btu a gallon as a measure of how efficient a glycol loop is. Why is that the wrong reading?', '["It falls as the circulation ratio rises, so it improves on the very move that raises the duty an hour.", "It is charged on the solvent rather than on the water, so it says nothing about how much water the loop removed.", "It is the same on every stream this module answers, so it cannot separate one loop from another at all.", "It rises with the still temperature, which a plant can move."]'::jsonb, 0, 'From 2.000000 to 5.000000 gal per lb the Btu a gallon runs from 2073.6650 down to 1661.1650 while the duty runs from 0.497666 up to 0.996673 MMBtu an hour.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 10, 'The spec, the circulation ratio and the reflux ratio enter the chain at three different heights. What follows from that?', '["Which of them the engine will choose for you, since the higher a lever sits the more likely the module is to carry a default.", "How much of the answer each one disturbs, since the spec moves everything below it and the reflux ratio reaches one heat term.", "How large each one''s effect is, since a lever near the top of a chain multiplies through more steps and therefore moves more.", "Which of them the published cases can check, since a golden covers the steps below the lever it varies and none above it."]'::jsonb, 1, 'The spec enters at the subtraction that makes the load. The ratio enters once the load stands in pounds a day. The reflux ratio enters inside the overhead term, and its reach is the shortest of the three.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 11, 'Each lever table holds every other input pinned. What must such a table not be used for?', '["Explaining the mechanism of the lever, since a table with everything else pinned cannot show what the lever acts through.", "Comparing two levers, since the columns of one table are not the columns of another and the rows are at different inputs.", "Predicting the outcome of a real change, in which more than one input usually moves at once.", "Checking the engine, since the table repeats one call."]'::jsonb, 2, 'A spec tightening usually arrives with a rate change. The tables give the direction and the mechanism of each lever completely, and the outcome of a decision that pulls two of them not at all.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 12, 'There is a fourth handle on a dehydration package that appears on none of the lever tables. What is it, and where does it sit?', '["The lean glycol strength, and it sits inside the regenerator, where the still temperature is what decides it.", "The gas pressure, and it sits at the compression the pipeline contract demands.", "The absorber temperature, and it sits at the bottom of the contactor where the rich glycol leaves.", "The gas temperature, and it sits upstream of the package in whatever cools the gas before the contactor."]'::jsonb, 3, 'Cooling the gas before it meets the glycol lowers the inlet content, so the load is smaller before any glycol is involved. Every pound taken out that way is one the loop never carries.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 13, 'On the three published TEG cases the water, gpm, Btu a gallon and MMBtu an hour columns all read 1.000000000000 against the golden while the BTEX column reads 0.999997865073. What separates the last column from the others?', '["It is the only column in the table that is a mole balance, and the others are mass balances.", "It is the only column the golden computes independently, and the others are re-read out of the engine''s own answer.", "It is the only column carrying an operating value, so the absorbed fraction the two sides assume is not the same number.", "It is the only column quoted a day rather than a gallon."]'::jsonb, 0, 'The check re-expresses the mass columns through kilograms and cubic metres and comes back to the same pounds. What the gap in the mole column is belongs to a later tier.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 14, 'The second published TEG case runs 120.000000 MMscfd from 90.000000 to 4.000000 lb per MMscf at 4.000000 gal per lb. Which figure is the circulation?', '["10320.0000, which is the circulation expressed the way the loop balance carries it.", "1789.7000, which is what a gallon of that circulation costs to regenerate.", "28.666667 gpm.", "3.078284, which is the circulation once the hours in a day have been applied to it."]'::jsonb, 2, '10320.0000 is the water a day, 1789.7000 is the duty a gallon and 3.078284 is the reboiler in MMBtu an hour. Four figures about one case and each answers a different question.'),
  ('gasprocessing', 'beginner', 'module', 'm05-a-dehydration-answer-end-to-end', 15, 'The engine reports the basis of the outlet water content on every dehydration answer. What does it say?', '["That the spec was derived from the lean strength, which is the input the loop water balance turns into a dew point.", "That the spec was typed, because the dew point lean glycol can deliver is a chart this module does not carry.", "That the spec was taken from the published cases.", "That the spec was checked against the customary band."]'::jsonb, 1, 'The module takes the spec and reports the loop balance that follows from it rather than pretending to derive one from the other. A reader who wants the other direction needs the chart.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Six answers are reported on OBIAFU. Which of them did not come through the water chain at all?', '["The circulation of 6.399830 gpm and the reboiler duty of 0.697269 MMBtu an hour, which are sizes.", "The water content of 53.450380 lb per MMscf and the load of 46.450380 lb per MMscf.", "The contactor diameter of 3.192661 ft and the 74.065024 short tons of aromatics a year.", "The 9215.7553 gallons a day and the duty per gallon of 1815.8525 Btu."]'::jsonb, 2, 'One belongs to a vessel calculation and the other to a mole balance, and both are taught in later tiers. Everything else on the reading is a step of the chain or the rate applied to one.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 2, 'The gas pressure alone moves and nothing else on the sheet changes. Which of the six answers is the one that cares about pressure for a reason other than how wet the gas is?', '["The contactor diameter, which is sized on what the gas weighs and how fast it may rise.", "The reboiler duty, which is charged on gallons and the gallons follow the pressure through the loop.", "The duty per gallon, which carries the still and absorber temperatures.", "The circulation, which the line conditions reach directly."]'::jsonb, 0, 'Pressure reaches the water chain through the inlet content and nowhere else. The vessel is sized by what the gas weighs, which is a question the water chain never asked.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 3, 'What is the practical use of sorting the six answers into properties, sizes and the vessel figure?', '["It says which of the six the engine computed and which of them a person typed in.", "It says which of the six the published TEG cases cover and which have no golden behind them.", "It says which of the six carry a warning at OBIAFU''s conditions and which come back clean.", "It says which figures to re-derive when the rate moves, which to leave alone, and which to check against a separate method."]'::jsonb, 3, 'Six figures on a data sheet arrive in the same font in the same table, and nothing on the page says that two are properties, three are sizes and one belongs to a different calculation.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Step one of the worked reading takes 950.000000 psia and 104.000000 degF to 53.450380 lb per MMscf. Which constants did it consume?', '["The three Magnus coefficients, the gallons in a cubic foot and the glycol density of 9.300000 lb a gallon.", "The three Magnus coefficients, the standard base of 14.696000 psia and 519.670000 degR, and the molecular weight of water.", "The standard base, the 1440.000000000 minutes in a day and the molecular weight of water.", "The Rankine offset of 459.670000 degR alone, since the fit is written on the absolute scale."]'::jsonb, 1, 'The coefficients give the vapour pressure, the standard base gives the standard cubic feet a pound mole of 379.483571856287, and 18.015280 turns a share of moles into pounds.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Step two takes the content to a load of 46.450380 lb per MMscf. What did that step consume?', '["The gas rate of 62.000000 MMscfd, which is what makes a content into a load.", "The circulation ratio of 3.200000 gal per lb, which is what the spec is applied through.", "No constant at all, and no rate has been mentioned yet.", "The molecular weight of water."]'::jsonb, 2, 'A contract allows 7.000000 lb per MMscf out, and the load is one subtraction. The rate arrives at the next step and the ratio at the one after that.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Step three multiplies the load by 62.000000 MMscfd to give 2879.9235 lb a day. What changed about the answer at that step?', '["It stopped being a property of the gas and became a property of the plant.", "It stopped being a mole figure and became a mass, since the rate is what carries the pound mole into it.", "It stopped being a design choice and became a computed result, since the rate is given to the plant rather than chosen.", "It stopped being intensive and became a ratio."]'::jsonb, 0, 'One multiplication, and the answer scales with how much gas there is from that point down. Everything above the step is per MMscf and knows nothing about the rate.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Step four turns 2879.9235 lb a day into 6.399830 gpm. Which figure in that step came from a person?', '["The 9215.7553 gallons a day, read off the loop the plant actually runs.", "The 1440.000000000 minutes in a day, which the module declares under a name.", "The 6.399830 gpm itself.", "The circulation ratio of 3.200000 gal of glycol per lb of water."]'::jsonb, 3, 'The load came from the contract and the conditions, and the minutes in a day were measured out of the engine. The ratio is the one number here that somebody chose.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Step five consumes two constants that no publication in this repository stands behind. Which two?', '["The standard cubic feet a pound mole and the molecular weight of water.", "The glycol at 9.300000 lb a gallon and the still overhead at 1100.000000 Btu a lb.", "The minutes in a day and the group factor.", "The gallons in a cubic foot of 7.480519480519 and the Rankine offset of 459.670000 degR."]'::jsonb, 1, 'Both are declared, and the step spends them on the two halves of the duty. The measured and derived figures in the reading belong to steps one, four and six.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Step six takes 9215.7553 gallons a day at 1815.8525 Btu a gallon to 0.697269 MMBtu an hour. What stands between them?', '["The 1440.000000000 minutes in a day.", "The gallons in a cubic foot, 7.480519480519.", "The group factor of 24000000.", "The sensible share of 0.763369."]'::jsonb, 2, 'The group carries the hours in a day and the Btu in a MMBtu together, because this module never uses the two separately and nothing outside it can pull them apart.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Two conversions appear in the worked reading, one at step four and one at step six. Which is which?', '["1440.000000000 at step four and 24000000 at step six.", "24000000 at step four and then 1440.000000000 at step six.", "1440.000000000 at both of them, once on the gallons and once on the Btu.", "7.480519480519 at step four and then 24000000 at step six."]'::jsonb, 0, 'The minutes in a day turn gallons a day into gallons a minute. The group factor turns a Btu a day into MMBtu an hour, and they sit two steps apart in the chain.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 11, 'A declared constant is simply the wrong number, and a measured one is exported under a name the engine does not use for it. How would each show up?', '["The measured one shows up in the published cases, and the declared one as a ratio away from 1.000000000000.", "The measured one shows up as a ratio away from 1.000000000000, and the declared one shows up nowhere at all.", "Both show up as a ratio away from 1.000000000000, since a constant is measured under the name it is declared with.", "The measured one shows up nowhere, since it was read out of the engine, and the declared one in the goldens."]'::jsonb, 1, 'A measurement compares the name on the page with the number in use, so a mismatch is exactly what it catches. A declared value that is the wrong number has no publication in this repository to check it against, and pinning it only makes a change to it a reviewed act.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 12, 'The next tier reads one contactor three separate ways. Which three?', '["As a staged device, as a heat balance, and as a vessel to size.", "As a mole balance, as a water balance, and as a dew point chart.", "As a staged device, as a mole balance, and as a hydrate margin.", "As a staged device, as a mole balance, and as a vessel."]'::jsonb, 3, 'The mole balance says how much solution has to move. The stage relation says whether the spec is reachable. The vessel says how wide the steel has to be, and not one of the three derives from the other two.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 13, 'The Professional tier introduces a limit that nothing in the Associate tier prepares a reader for. What is it?', '["A duty the reboiler cannot pass however hot the still is run, whose remedy is a lower circulation ratio.", "A width the contactor cannot pass however fast the gas rises, whose remedy is a second column in parallel.", "A removal the column cannot pass however many stages are added, whose remedy is more solvent rather than more steel.", "A spec the loop cannot pass however strong the lean solution is, whose remedy is a colder gas at the inlet."]'::jsonb, 2, 'In the water chain, tightening the spec always worked and an answer always came back. A staged column has a ceiling in it, and the engine says so rather than returning a number nobody can reach.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 14, 'UBIE goes to the Professional tier as a mole balance, at 10666.2009 lbmol of acid gas a day. What does that route have in common with the glycol chain?', '["Nothing in the method. There is no water content in it, no circulation ratio, and the solvent comes from a property table.", "The circulation ratio, which is what turns either pickup into a solution rate in gpm.", "The saturation step, which fixes what the gas carries before either spec is applied to it.", "The duty a gallon, which both loops assemble from a sensible term and an overhead term."]'::jsonb, 0, 'Both end at a circulation and a duty, and the methods that reach them have nothing in common. The amine duty a gallon is a stated figure rather than one assembled from named parts, and the solvent is chosen from a published property table.'),
  ('gasprocessing', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does this course ask at every tier, with only the answers changing?', '["Which number the published cases cover, which one the golden reaches by a second road, and which one nothing checks.", "Which number the engine computed, which one you chose, and which one it kept to itself.", "Which number is intensive, which is extensive, and which belongs to a vessel.", "Which number the studio prints, which one the digest prints, and which one only the engine holds."]'::jsonb, 1, 'The discipline is the reason the water chain came first. The three questions are the same on a Kremser removal and on a Joule-Thomson coefficient as on a circulation in gpm.'),
  ('gasprocessing', 'beginner', 'final', null, 1, 'Which of these is a question this engine has no answer for at all?', '["How wide the contactor the gas has to rise through against a falling liquid has to be.", "How far a let-down cools the gas that passes through it.", "Whether the dried gas sits inside a hydrate margin at line conditions.", "What the regenerator costs to run on the gas it is given."]'::jsonb, 2, 'A hydrate margin belongs to the Flow Assurance engine in the Production module. The other three are among the five questions this engine answers on one stream.'),
  ('gasprocessing', 'beginner', 'final', null, 2, 'A figure in this module is a chart value that no first principle reaches. How does the doctrine in the module header say it must arrive?', '["As a constant exported under a name and computed from the standard base this module fixes.", "As a value the published cases pin, so that changing it breaks a golden and the change is reviewed.", "As an input with a default and its customary range named, where a reader can see it.", "As a figure the studio asks for on every call, with no default at all."]'::jsonb, 2, 'Everything that is a design choice or a chart value is an input. Everything computable from first principles is computed. A number you can see is a number you can argue with.'),
  ('gasprocessing', 'beginner', 'final', null, 3, 'The gallons in a cubic foot, 7.480519480519, is exact as 1728 cubic inches to the cubic foot over 231 to the gallon. Which kind of constant is it?', '["Measured, so a ratio of the measurement over the export says the two agree.", "Declared, so pinning it is the whole of what a gate can offer.", "Published, so a golden built on a second source can check it.", "Derived, so there is nothing separate to check."]'::jsonb, 3, 'A derived constant is computed from something the module already exports or from an exact definition, and it cannot be wrong unless its parent is.'),
  ('gasprocessing', 'beginner', 'final', null, 4, 'The amine gallons chain divides by a water density of 8.340000 lb a gallon. What standing does that figure have here?', '["Derived, from the glycol density and the gallons in a cubic foot.", "Declared, so it can be pinned under a name and nothing in this package can check it.", "Measured, out of an answer where the vaporization term stands alone.", "Published, and checked by the oracle through a second route in SI units."]'::jsonb, 1, 'A declared constant is customary or read off a chart. Exporting it under a name makes a change to it a reviewed act, and that is the whole of what any gate in this repository can offer.'),
  ('gasprocessing', 'beginner', 'final', null, 5, 'A dehydration call cannot answer. What reaches the studio, and what does the studio do to notice?', '["A thrown error, noticed by catching around the call.", "A null, noticed by comparing the return against it.", "A NaN, noticed by testing whether the number that came back is a finite one at all, rather than a hole.", "An object with a named string on an error key, noticed by asking it for one property."]'::jsonb, 3, 'Nothing in this module throws, so the tab can print the refusal rather than falling over, and the refusal says what was wrong and what would fix it.'),
  ('gasprocessing', 'beginner', 'final', null, 6, 'The Rankine offset of 459.670000 degR and the gas constant of 10.731600 are used throughout this module. Where are they exported from?', '["The separator sizing module, which the contactor shares its K value with.", "This module''s own declared constants, beside the Magnus three.", "The standard base, which both of them are derived from.", "The gas properties door of the package, rather than from this module."]'::jsonb, 3, 'They belong to the package rather than to this module, which reads them. The standard cubic feet a pound mole is what this module derives from the gas constant and its own base.'),
  ('gasprocessing', 'beginner', 'final', null, 7, 'Why does this module export every constant it uses under a name?', '["So the published cases can vary each one of them in turn and record exactly what moved.", "So a reader can point at the number rather than infer it from an answer.", "So the studio can offer every one of them as a box on the page.", "So a gate can re-derive each one from the publication it came from."]'::jsonb, 1, 'Naming a constant is what makes the difference between the three kinds visible at all, and it is what lets the digest measure four of them back out of return values.'),
  ('gasprocessing', 'beginner', 'final', null, 8, 'At 1000.000000 psia the water content reads 12.144308 lb per MMscf at 60.000000 degF. What does it read at 140.000000 degF?', '["8.096205 lb per MMscf.", "91.910902 lb a MMscf.", "137.866352 lb per MMscf.", "229.777254 lb a MMscf."]'::jsonb, 2, 'Down a column of that surface the content rises with the vapour pressure. The other three figures are the 1500 psia column at 60 and at 140 degF, and the 600 psia reading at 140 degF.'),
  ('gasprocessing', 'beginner', 'final', null, 9, 'Three limits sit on the water answer. Which of them refuses rather than warning?', '["The temperature band the vapour-pressure fit holds over.", "The narrower band the Magnus coefficients were published over.", "The pressure above which ideal mixing understates the water.", "The customary circulation band the glycol loop is designed in."]'::jsonb, 0, 'Outside the fit band the formula has no claim on the curve, so refusing is the only defensible thing to do. The other two answer and attach a note, and the circulation band is not on the water answer at all.'),
  ('gasprocessing', 'beginner', 'final', null, 10, 'The module guards from -45 to 60 degC and the coefficients behind the fit were published from -40 to 50 degC. What is a reader holding inside the gap between the two upper figures?', '["A flagged reading, which the engine returns with a note saying the fit is being extrapolated there.", "A refusal, since the published band is the one the guard is written on.", "A clean reading, since the guard band is the one that decides whether a note is attached.", "A chart reading, since the note in that gap sends the reader to the McKetta-Wehe correction."]'::jsonb, 0, 'Two bands with two different jobs. Outside the wider one the formula has no claim on the curve at all, which is why one of them refuses and the other only flags.'),
  ('gasprocessing', 'beginner', 'final', null, 11, 'Which of these is refused by the water answer rather than warned about?', '["A gas temperature of -600 degF.", "A total pressure of 1500 psia, which is the last column of the water surface.", "A gas temperature of 122.000001 degF.", "A circulation ratio of 6.000000 gal per lb."]'::jsonb, 0, 'A temperature below absolute zero is refused by name, and so is a pressure of zero. The other two answer with a note attached, and one of them is not on the water answer at all.'),
  ('gasprocessing', 'beginner', 'final', null, 12, 'A reader divides the 253.889303 cell of the water surface by the 84.629768 cell and calls the result how the surface behaves with pressure. What is wrong with that?', '["The two cells sit at different temperatures, so the ratio describes the temperature direction instead.", "The ratio is right but incomplete, since it holds only at the two pressures those cells were read at.", "The cells are in lb per MMscf, so their ratio carries a unit that has to be divided out first.", "The course prints both cells and prints no ratio between them, so the comparison is one nothing in this engine computes."]'::jsonb, 3, 'A number nobody computed reads exactly like one somebody did. What the table supports is the direction, which is that a tighter gas carries less water at every temperature in it.'),
  ('gasprocessing', 'beginner', 'final', null, 13, 'At a fixed temperature the total pressure is raised. What happens to the water the gas can carry, and why?', '["It falls, because the vapour pressure itself is pushed down by the compression.", "It rises, because a denser gas carries more water past the same point.", "It holds level, because the pressure cancels out again in the pound mole.", "It falls, since pressure enters this method only underneath, as a divisor."]'::jsonb, 3, 'Two independent handles, one on top and one underneath. Squeezing the gas spreads the same amount of water vapour through more molecules of gas, so the fraction falls.'),
  ('gasprocessing', 'beginner', 'final', null, 14, 'Of the four published water cases, which condition carries the largest departure from the golden?', '["500.000000 psia and 100.000000 degF, at 1.001865077.", "65.000000 psia and 40.000000 degF, at 1.006379500.", "1000.000000 psia and 120.000000 degF, at 1.004159870.", "200.000000 psia and 60.000000 degF, at 1.002457408."]'::jsonb, 1, 'All four sit near one rather than at one, because the golden uses a different published vapour-pressure equation. Two independent fits of one curve meeting inside their shared band is the result the check is after.'),
  ('gasprocessing', 'beginner', 'final', null, 15, 'At a spec of 2.000000 lb per MMscf, OBIAFU takes out 3189.9235 lb a day and circulates 7.088719 gpm. Which of those two figures would be unchanged by a move in the circulation ratio?', '["The 3189.9235 lb a day.", "The 7.088719 gpm.", "Both of them, since the ratio reaches neither.", "Neither of them, since the ratio reaches both."]'::jsonb, 0, 'The same pounds still come out of the same gas whatever the ratio is. What the ratio moves is how many gallons carry them and what each gallon costs.'),
  ('gasprocessing', 'beginner', 'final', null, 16, 'At 30.000000 MMscfd the removal is 1393.5114 lb a day, the circulation 3.096692 gpm and the duty per gallon 1815.8525 Btu. Which of the three carries the rate inside it?', '["The removal alone, since the other two are loop figures.", "The removal and the circulation, and not the duty per gallon.", "All three, since every figure below the load carries the rate.", "The circulation alone, since it is the only one quoted a minute."]'::jsonb, 1, 'The rate enters at one multiplication and everything below that point scales with it. The duty per gallon reads 1815.8525 at every rate in the table.'),
  ('gasprocessing', 'beginner', 'final', null, 17, 'Two rows of the circulation ratio table carry a warning, at 1.500000 and at 6.000000 gal per lb. What does the engine do on those rows?', '["It refuses, because a ratio outside the customary band is one the module will not size.", "It answers and clamps the ratio to the nearer edge of the band before using it.", "It answers, and says the ratio sits outside the customary 2.000000 to 5.000000 gal per lb.", "It answers only on the low row and refuses on the high one, where the loop runs dry."]'::jsonb, 2, 'Both flagged rows carry full results beside the flag, 2302.8317 Btu a gallon at the low one and 1615.3317 at the high one. The flag is advisory and the figures are ordinary answers.'),
  ('gasprocessing', 'beginner', 'final', null, 18, 'At 1.500000 gal per lb the overhead is 916.6667 Btu a gallon against a sensible term of 1386.1650. What does that pair of figures say about the loop?', '["Each gallon is heavily loaded with water, so the overhead has climbed towards the sensible term.", "The still is running hotter than the default, which is what lifts the overhead.", "The reflux ratio has been raised, since the reflux is charged inside the overhead.", "The loop is lightly loaded, since a low ratio means fewer gallons and less water in each."]'::jsonb, 0, 'A low ratio means fewer gallons each carrying more water. The sensible term sits at 1386.1650 the length of that table because the temperature rise per gallon never changed.'),
  ('gasprocessing', 'beginner', 'final', null, 19, 'At 1.999999 gal per lb the engine warns that the ratio is outside the customary 2.000000 to 5.000000 gal per lb, and adds no second sentence to it. Why not?', '["The ratio is inside the customary band, so no warning of any kind is raised.", "The rich strength is not reported at that ratio, so nothing can be said about it.", "The rich strength is still above the 90 the module accepts as a lean one.", "The second sentence is attached to the lean strength rather than to the ratio."]'::jsonb, 2, 'A millionth outside the customary edge is still a loop that is intact at the rich end, which at 2.000000 gal per lb returns at 94.138775510 weight percent. At 1.000000 gal per lb the rich returns at 89.568932039 and the sentence appears.'),
  ('gasprocessing', 'beginner', 'final', null, 20, 'A lean gallon carries 0.465000000 lb of water at 95.000000 weight percent and 0.009300000 lb at 99.900000. What is that table saying?', '["A stronger lean solution arrives at the contactor carrying less water of its own.", "A stronger lean solution picks up less water from the gas on its way down.", "A stronger lean solution returns rich at a lower strength, since it has further to fall.", "A stronger lean solution sets a tighter outlet spec on the gas leaving the contactor."]'::jsonb, 0, 'A gallon of lean solution is not pure glycol, and at w weight percent it already carries water before it meets the gas. What it does not do is set the outlet spec, and the engine says so on every answer.'),
  ('gasprocessing', 'beginner', 'final', null, 21, 'A lean strength of 90.000001000 weight percent is accepted and the rich glycol comes back at 87.074123 weight percent. What does that show?', '["The guard is inclusive at its lower edge, since a value that close to 90 was accepted.", "The strength guard is on the lean solution, and the rich end can still fall below the same limit.", "The rich strength is what the guard actually tests, one step after the lean is read.", "The loop is refused a step later, since a rich below 90 is not a dehydration loop."]'::jsonb, 1, 'The lean band is exclusive at both edges and it is read on the lean solution as it enters the contactor. What the rich end comes back at is reported rather than guarded, which is why a lean just inside the band can return a rich well below it.'),
  ('gasprocessing', 'beginner', 'final', null, 22, 'At a reflux ratio of 0.600000 the overhead is 550.0000 Btu a gallon and the total is 1936.1650. Which term did the reflux ratio not touch?', '["The total, which moves only with the still temperature.", "The sensible term, which the still and the absorber fix between them.", "The overhead, which is charged on the solvent rather than on the water.", "The duty an hour, which is charged on the gallons a day rather than on one."]'::jsonb, 1, 'Everything in that table is charged on the water a gallon carries. Nothing in it is charged on the solvent, so 1386.1650 Btu a gallon reads the same on every row.'),
  ('gasprocessing', 'beginner', 'final', null, 23, 'The still is moved to 360.000000 degF and the total becomes 1739.1275 Btu a gallon. Which term moved?', '["The overhead term, to 429.6875 Btu a gallon.", "Both terms, in proportion to the temperature rise.", "Neither term, since the total is charged separately.", "The sensible term, to 1309.4400 Btu a gallon."]'::jsonb, 3, 'Only the rise moved, from a still at 375.000000 degF down to one at 360.000000. The other half of the duty reads 429.6875 Btu a gallon on every row of that table.'),
  ('gasprocessing', 'beginner', 'final', null, 24, 'One of the two heat terms is charged on the solvent and the other on the water. Which is which, and what follows?', '["The sensible term is charged on the water and the overhead on the solvent, so the still temperature reaches the overhead.", "Both are charged on the solvent, and the water enters only through the gallons a day.", "The sensible term is charged on the solvent and the overhead on the water, so they answer to different inputs.", "Both are charged on the water, and the solvent enters only through the density."]'::jsonb, 2, 'The sensible half follows the still temperature and the absorber temperature. The overhead half follows the circulation ratio and the reflux ratio, and neither cares much about the other.'),
  ('gasprocessing', 'beginner', 'final', null, 25, 'The reboiler reads 0.664270 MMBtu an hour at a reflux ratio of 0.000000 and 0.697269 at 0.250000. What is the difference between the two?', '["The heat the condenser removes at the top of the column, now charged to the reboiler.", "The glycol the loop loses overhead when no reflux is run, priced as duty.", "The heat the reboiler pays again on the water the still condenses and boils a second time.", "The extra sensible heat the returning liquid needs to reach the still again."]'::jsonb, 2, 'The reflux ratio adds its fraction of the water vaporization on top of itself. What it saves in glycol carryover is not a quantity this engine computes.'),
  ('gasprocessing', 'beginner', 'final', null, 26, 'A reviewer proposes changing the 1100.000000 Btu a lb the still overhead is charged at. What can a gate do about the proposal?', '["Re-derive it from the standard base and refuse any value that disagrees with the result.", "Pin the value, so that moving it is a reviewed act rather than a quiet edit.", "Check it against the published TEG cases, which all three carry it.", "Measure it back out of the engine and refuse a ratio away from one."]'::jsonb, 1, 'It is a declared value with no publication in this repository behind it. Measuring it back out of an answer shows the name and the number in use agree, which is a different claim from the value being right.'),
  ('gasprocessing', 'beginner', 'final', null, 27, 'The sensible share of the OBIAFU duty is 0.763369. What is that figure for?', '["It is the fraction of the duty that moves when the circulation ratio moves.", "It says which of the two halves this reboiler is mostly spending its firing on.", "It is the share of the duty the published cases are able to check.", "It is the fraction of each gallon that reaches the still as liquid glycol."]'::jsonb, 1, 'It is printed because a reader meets both halves and would otherwise form the comparison unaided. On OBIAFU most of the firing goes on getting glycol up to the still.'),
  ('gasprocessing', 'beginner', 'final', null, 28, 'A loop at 1.500000 gal per lb costs 2302.8317 Btu a gallon and one at 6.000000 costs 1615.3317. Which of the two reboilers is the larger, and by what reading?', '["The 1.500000 gal per lb loop, since a gallon there costs more.", "The 6.000000 gal per lb loop, at 1.163008 against 0.414499 MMBtu an hour.", "Neither, since the duty an hour is the same once all the gallons are counted.", "The 1.500000 gal per lb loop, since both its heat terms are larger."]'::jsonb, 1, 'A duty a gallon says what one gallon costs and nothing about how many gallons there are. Reading the cheaper gallon as the cheaper loop is the misreading this tier spends a module on.'),
  ('gasprocessing', 'beginner', 'final', null, 29, 'Which lever moves the gallons a minute and the heat a gallon while leaving the water removed a day exactly where it was?', '["The choice of how many gallons of glycol carry each pound of water.", "The outlet spec on the gas.", "The gas rate in MMscfd.", "The gas temperature."]'::jsonb, 0, 'The other three reach the load, and everything below the load moves with them. The ratio enters once the load already stands in pounds a day.'),
  ('gasprocessing', 'beginner', 'final', null, 30, 'A duty an hour has risen while the duty a gallon has fallen, and the gas rate and the spec are unchanged. What moved?', '["The still temperature, raised.", "The circulation ratio, upwards.", "The reflux ratio, raised.", "The lean glycol strength, upwards."]'::jsonb, 1, 'Raising the ratio adds gallons and lightens each one, so the two duty columns go in opposite directions down the same table. The still temperature and the reflux ratio raise both.'),
  ('gasprocessing', 'beginner', 'final', null, 31, 'The third published TEG case reports 5135.0000, 8.914931, 2204.0250, 1.178924 and 457.5376. Which of those is what a gallon costs to regenerate?', '["2204.0250 Btu a gallon.", "8.914931, which is the gallons that cost is charged on.", "1.178924, which is the same cost as a firing rate.", "457.5376, which is what leaves through the still overhead."]'::jsonb, 0, 'Five figures from one case and only one of them is charged on a gallon. The 8.914931 is the gallons a minute and the 1.178924 is the firing rate those gallons demand.'),
  ('gasprocessing', 'beginner', 'final', null, 32, 'A check agrees with the engine whatever the engine does. What has it established?', '["That the engine reproduces, which is what a golden is for.", "That the arithmetic is faithful, though not that the inputs are right.", "That the two sides share a route, which is the strongest agreement available.", "Nothing, because a check that restates what it is checking cannot fail."]'::jsonb, 3, 'Ask what the check would do if the answer were wrong. If the honest response is that it would agree anyway, the check is decoration. The mass columns of the TEG cases reach the same pounds through kilograms and cubic metres.'),
  ('gasprocessing', 'beginner', 'final', null, 33, 'OBIAFU runs a lean glycol strength of 99.200000 weight percent. What does the engine report about the loop at that strength?', '["A lean gallon carrying 0.312500000 lb of water at that point, and rich glycol returning at 95.975032510 weight percent.", "A dew point of 7.000000 lb per MMscf, which is the spec that strength can deliver.", "A rich strength of 99.200000 weight percent, since the lean figure is what the loop returns to.", "A lean gallon carrying 0.074400000 lb of water already, and rich glycol returning at 95.975032510 weight percent."]'::jsonb, 3, 'A gallon of lean solution is not pure glycol. The 0.312500000 lb is what the gallon picks up from the gas at this circulation ratio, which is a different quantity from the water it arrived carrying.'),
  ('gasprocessing', 'beginner', 'final', null, 34, 'Two of the load a day, the circulation ratio and the gallons a minute always give the third. Which pair gives the ratio?', '["The gallons a minute alone, read against the customary band.", "The load a day and the reboiler duty an hour.", "The gallons a minute and the duty a gallon.", "The load a day and the gallons a minute."]'::jsonb, 3, 'That is why a single quoted circulation says almost nothing on its own. The duty figures sit below the ratio in the chain and cannot be read back through it.'),
  ('gasprocessing', 'beginner', 'final', null, 35, 'In what order does this course say a dehydration duty answer should be read?', '["The MMBtu an hour first, then the Btu a gallon, then the gallons a day.", "The gallons a day first, then the MMBtu an hour, and the Btu a gallon at the end.", "Read the duty a gallon first, the gallons a day next, and the hourly figure last.", "The MMBtu an hour alone, since the other two are inside it already."]'::jsonb, 2, 'Ask whether the loop looks sensible, then whether the plant looks the right size. The hourly duty is the product of two judgements already made, which is why it is read last.'),
  ('gasprocessing', 'beginner', 'final', null, 36, 'Of the six answers on the OBIAFU reading, which pair would read exactly the same at any gas rate whatever?', '["The 2879.9235 lb a day and the 6.399830 gpm.", "The 53.450380 lb per MMscf and the 1815.8525 Btu a gallon.", "The 9215.7553 gallons a day and the 0.697269 MMBtu an hour.", "The 3.192661 ft and the 74.065024 short tons a year."]'::jsonb, 1, 'One is a property of the gas at its conditions and the other a property of the glycol loop. Three of the six are those two with the rate applied, and the last two come from outside the water chain.'),
  ('gasprocessing', 'beginner', 'final', null, 37, 'The 74.065024 short tons of aromatics a year belongs to which calculation?', '["The loop water balance, which reports what a lean gallon carries.", "The vessel sizing, which is the other figure from outside the water chain.", "The reboiler duty, since the aromatics leave with the water it boils off.", "A mole balance on what the glycol carries round the loop and out through the still overhead."]'::jsonb, 3, 'It is taught in a later tier. On the Associate reading it is recorded as a figure that did not come through any step of the water chain.'),
  ('gasprocessing', 'beginner', 'final', null, 38, 'In the worked reading, which step is the first one that could not have been taken without a number somebody chose?', '["The step that turns a mole fraction of 0.001125908 into 53.450380 lb per MMscf.", "The step that turns 53.450380 lb per MMscf into a load of 46.450380 lb.", "The step that turns 2879.9235 lb a day into 9215.7553 gallons a day.", "The step that turns 46.450380 lb per MMscf into 2879.9235 lb a day."]'::jsonb, 2, 'The content came from the conditions, the spec from a contract and the rate from the reservoir. The circulation ratio of 3.200000 gal per lb came from a person.'),
  ('gasprocessing', 'beginner', 'final', null, 39, 'Which figure in the worked reading is measured back out of the engine rather than declared or derived?', '["The 1440.000000000 minutes in a day.", "The 9.300000 lb a gallon the glycol weighs.", "The 0.550000 Btu per lb per degF.", "The 0.250000 reflux ratio."]'::jsonb, 0, 'It is the gallons a day over the gallons a minute of one call. The other three are values the caller supplies or the module declares, and no measurement inside the package reaches them.'),
  ('gasprocessing', 'beginner', 'final', null, 40, 'What did the Associate tier never ask about the contactor?', '["How the water actually leaves the gas inside it.", "How wide it has to be at the conditions the gas arrives at.", "How much water it has to take out of the gas each day.", "What the solvent running down it costs to regenerate."]'::jsonb, 0, 'This tier treated the column as a place where water leaves the gas. The next one asks how, and a device with stages in it turns out to carry a limit that this chain has nothing like.'),
  ('gasprocessing', 'beginner', 'final', null, 41, 'UBIE reports 10666.2009 lbmol a day and OBIAFU reports 6.399830 gpm. What is the difference between the two questions those figures answer?', '["One is a rate and the other a quantity, so they differ only in the time unit.", "One is a mole balance and the other a mass balance on the same solvent loop.", "One is how much acid gas has to be picked up, and the other how much solvent has to move.", "One is an inlet figure and the other an outlet figure on the same column."]'::jsonb, 2, 'The pickup is what the specs demand of the solution, and the circulation is what carries it. They belong to different streams and different solvents in this course.'),
  ('gasprocessing', 'beginner', 'final', null, 42, 'Three questions are asked of every figure at every tier of this course. What are they?', '["Did the engine compute it, did you choose it, or did it keep the answer to itself.", "Is it intensive, is it extensive, or does it belong to the vessel calculation instead.", "Is it a derived constant, is it a measured one, or is it a declared one with nothing behind it.", "Did a golden check it, did a gate pin it, or does nothing reach it."]'::jsonb, 0, 'The other three groupings are real and each one answers a narrower question. The three above are the discipline the whole course is built on, and only the answers change from tier to tier.');
